CREATE TABLE users (id BIGSERIAL PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, display_name VARCHAR(120) NOT NULL, department VARCHAR(80), enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE user_roles (user_id BIGINT NOT NULL REFERENCES users(id), role VARCHAR(30) NOT NULL CHECK (role IN ('STUDENT','APPLICANT','ADMIN','TECHNICIAN')), PRIMARY KEY(user_id,role));
CREATE TABLE classrooms (id BIGSERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, building VARCHAR(120) NOT NULL, floor INTEGER NOT NULL, department VARCHAR(80), open_time TIME NOT NULL, close_time TIME NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, CHECK(close_time>open_time));
CREATE TABLE seats (id BIGSERIAL PRIMARY KEY, classroom_id BIGINT NOT NULL REFERENCES classrooms(id), label VARCHAR(40) NOT NULL, has_power BOOLEAN NOT NULL DEFAULT FALSE, enabled BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(classroom_id,label));
CREATE TABLE settings (id INTEGER PRIMARY KEY CHECK(id=1), max_reservation_hours INTEGER NOT NULL CHECK(max_reservation_hours BETWEEN 1 AND 12));
INSERT INTO settings VALUES(1,4);
CREATE TABLE reservations (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), seat_id BIGINT NOT NULL REFERENCES seats(id), start_time TIMESTAMPTZ NOT NULL, end_time TIMESTAMPTZ NOT NULL, status VARCHAR(30) NOT NULL CHECK(status IN('PENDING','CHECKED_IN','CANCELLED','NO_SHOW','COMPLETED')), check_in_deadline TIMESTAMPTZ NOT NULL, checked_in_at TIMESTAMPTZ, cancel_reason VARCHAR(80), created_at TIMESTAMPTZ NOT NULL, CHECK(end_time>start_time));
CREATE TABLE seat_slots (seat_id BIGINT NOT NULL REFERENCES seats(id), slot_start TIMESTAMPTZ NOT NULL, reservation_id BIGINT NOT NULL REFERENCES reservations(id), PRIMARY KEY(seat_id,slot_start));
CREATE TABLE restrictions (source_type VARCHAR(2) NOT NULL CHECK(source_type IN('M2','M3')), source_id BIGINT NOT NULL, version BIGINT NOT NULL CHECK(version>0), active BOOLEAN NOT NULL, classroom_id BIGINT NOT NULL REFERENCES classrooms(id), start_time TIMESTAMPTZ NOT NULL, end_time TIMESTAMPTZ, command_hash VARCHAR(64) NOT NULL, actor_id BIGINT NOT NULL REFERENCES users(id), request_id VARCHAR(100) NOT NULL, updated_at TIMESTAMPTZ NOT NULL, released_at TIMESTAMPTZ, PRIMARY KEY(source_type,source_id), CHECK(end_time IS NULL OR end_time>start_time));
CREATE TABLE violations (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), reservation_id BIGINT NOT NULL REFERENCES reservations(id), reason VARCHAR(50) NOT NULL, created_at TIMESTAMPTZ NOT NULL, UNIQUE(reservation_id,reason));
CREATE TABLE check_in_codes (classroom_id BIGINT NOT NULL REFERENCES classrooms(id), campus_date DATE NOT NULL, code_hash VARCHAR(100) NOT NULL, PRIMARY KEY(classroom_id,campus_date));
CREATE TABLE check_in_attempts (reservation_id BIGINT PRIMARY KEY REFERENCES reservations(id), failures INTEGER NOT NULL DEFAULT 0, last_attempt TIMESTAMPTZ NOT NULL);
CREATE TABLE idempotency_results (user_id BIGINT NOT NULL REFERENCES users(id), action VARCHAR(120) NOT NULL, request_key VARCHAR(150) NOT NULL, request_hash VARCHAR(64) NOT NULL, result_json TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, PRIMARY KEY(user_id,action,request_key));
CREATE TABLE audit_logs (id BIGSERIAL PRIMARY KEY, actor_id BIGINT REFERENCES users(id), action VARCHAR(120) NOT NULL, object_type VARCHAR(80) NOT NULL, object_id BIGINT, request_id VARCHAR(100) NOT NULL, created_at TIMESTAMPTZ NOT NULL);
